"""Fetch and normalize Coval simulation metric outputs for benchmark artifacts."""

from __future__ import annotations

import asyncio
import time
from typing import Any, Dict, List, Optional

from rasa.builder.copilot.mcp_server.tools.coval.agents import (
    RASA_CI_HYBRID_DETECTION_METRIC_IDS,
    RASA_CI_HYBRID_METRIC_LABELS,
)
from rasa.builder.copilot.mcp_server.tools.coval.client import CovalClient

_NON_TERMINAL_METRIC_STATUSES = frozenset({"IN QUEUE", "IN PROGRESS"})


def normalize_coval_metric_output(
    raw: Dict[str, Any],
    *,
    metric_name: Optional[str] = None,
) -> Dict[str, Any]:
    """Return a stable, artifact-friendly view of one Coval metric output."""
    resolved_name = metric_name or raw.get("metric_name")
    payload: Dict[str, Any] = {
        "metric_id": raw.get("metric_id"),
        "metric_name": resolved_name,
        "metric_output_id": raw.get("metric_output_id"),
        "status": raw.get("status"),
        "value": raw.get("value"),
    }
    explanation = raw.get("explanation")
    if explanation:
        payload["explanation"] = explanation
    return payload


def _is_detection_metric(
    metric_name: Optional[str],
    metric_id: Optional[str],
) -> bool:
    if metric_id and metric_id in RASA_CI_HYBRID_DETECTION_METRIC_IDS:
        return True
    if metric_name:
        return metric_name in {
            RASA_CI_HYBRID_METRIC_LABELS[metric_id]
            for metric_id in RASA_CI_HYBRID_DETECTION_METRIC_IDS
        }
    return False


def format_coval_metric_value(
    value: Any,
    *,
    metric_name: Optional[str] = None,
    metric_id: Optional[str] = None,
) -> str:
    """Format a Coval metric value for human-readable reports."""
    if value is None:
        return "—"
    if isinstance(value, bool):
        is_detection = _is_detection_metric(metric_name, metric_id)
        passed = not value if is_detection else value
        return "PASS" if passed else "FAIL"
    if isinstance(value, float):
        return f"{value:g}"
    if isinstance(value, list):
        return ", ".join(str(item) for item in value)
    return str(value)


async def _resolve_metric_labels(
    client: CovalClient,
    metric_ids: List[str],
    labels: Dict[str, str],
) -> Dict[str, str]:
    """Best-effort metric id → display name resolution."""
    resolved = dict(labels)
    for metric_id in metric_ids:
        if not metric_id or metric_id in resolved:
            continue
        try:
            metric = await client.get_metric(metric_id)
        except Exception:
            continue
        name = metric.get("metric_name") or metric.get("display_name")
        if name:
            resolved[metric_id] = str(name)
    return resolved


async def fetch_simulation_coval_metrics(
    client: CovalClient,
    simulation_id: str,
    *,
    poll_interval_s: float = 5.0,
    max_wait_s: float = 120.0,
    metric_labels: Optional[Dict[str, str]] = None,
) -> List[Dict[str, Any]]:
    """List Coval metric outputs for a simulation, polling until terminal or timeout."""
    labels = dict(metric_labels or RASA_CI_HYBRID_METRIC_LABELS)
    deadline = time.monotonic() + max_wait_s
    last_outputs: List[Dict[str, Any]] = []

    while time.monotonic() < deadline:
        raw_outputs = await client.list_simulation_metrics(simulation_id)
        metric_ids = [
            str(item.get("metric_id"))
            for item in raw_outputs
            if isinstance(item, dict) and item.get("metric_id")
        ]
        labels = await _resolve_metric_labels(client, metric_ids, labels)

        normalized = [
            normalize_coval_metric_output(
                item,
                metric_name=labels.get(str(item.get("metric_id"))),
            )
            for item in raw_outputs
            if isinstance(item, dict)
        ]
        last_outputs = sorted(
            normalized,
            key=lambda item: (
                str(item.get("metric_name") or ""),
                str(item.get("metric_id") or ""),
            ),
        )
        expected_metric_ids = frozenset(labels.keys())
        present_metric_ids = {
            str(item.get("metric_id")) for item in last_outputs if item.get("metric_id")
        }
        all_expected_present = expected_metric_ids.issubset(present_metric_ids)
        all_terminal = not any(
            str(item.get("status", "")).upper() in _NON_TERMINAL_METRIC_STATUSES
            for item in last_outputs
        )
        if last_outputs and all_expected_present and all_terminal:
            return last_outputs
        await asyncio.sleep(poll_interval_s)

    return last_outputs
